// Field sites on a Georgia outline (scripts/prepare-map.py, Natural Earth, public domain).
// Markers link to their cards, so the map works without JavaScript; site.js only adds highlighting.
const georgia = JSON.parse(await readFile(new URL('../scripts/data/georgia-outline.json', import.meta.url), 'utf8'));
const project = ([lat, lon]) => [(lon - georgia.projection.lonMin) * georgia.projection.kx * georgia.projection.k, (georgia.projection.latMax - lat) * georgia.projection.k].map(v => Math.round(v * 10) / 10);
const fieldSites = [
  { id:'athens', name:'Athens', kicker:'Home base', at:[33.948, -83.377], marker:[0, 0], label:[-16, 5, 'end'], text:'The lab’s home at the UGA College of Engineering: research, instrumented vehicles, and student projects.', image:'assets/research-vehicle.png', alt:'Sensor-equipped UGA research vehicle', link:['team.html', 'Meet the team'] },
  { id:'ga-72', name:'GA-72, Hull to Comer', kicker:'EV experiments', route:[[34.0151, -83.2949], [34.0637, -83.1252]], marker:[34, -30], label:[16, 5, 'start'], short:'GA-72', text:'EV platoon experiments on a straight, low-traffic stretch of State Route 72, comparing one-pedal and two-pedal driving.', image:'assets/ev-car-following-route-red', alt:'Map of the GA-72 experiment route between Hull and Comer', credit:'Map data © OpenStreetMap contributors', link:['resources.html#ev-platoon', 'Explore the dataset'] },
  { id:'hawkinsville', name:'Hawkinsville', kicker:'Rural AV route · TRAVELS', at:[32.2838, -83.4724], marker:[0, 0], label:[16, 5, 'start'], text:'A 3-mile demonstration loop past the regional hospital in Pulaski County, surveyed with LiDAR and mapped lane by lane.', image:'assets/lab-travels-pulaski-visit-2026.png', alt:'UGA researchers and local officials beside the research vehicle in Pulaski County', credit:'Photo: TRAVELS Center', link:['travels.html', 'Read the case study'] },
];
const fieldMap = (() => {
  const atlanta = project([33.749, -84.388]);
  const marks = fieldSites.map((site, i) => {
    const route = site.route?.map(project);
    const anchor = route ? route.reduce((a, p) => [a[0] + p[0] / route.length, a[1] + p[1] / route.length], [0, 0]) : project(site.at);
    const [x, y] = [anchor[0] + site.marker[0], anchor[1] + site.marker[1]];
    const leader = site.marker[0] || site.marker[1] ? `<line class="ga-leader" x1="${anchor[0].toFixed(1)}" y1="${anchor[1].toFixed(1)}" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}"/>` : '';
    const path = route ? `<polyline class="ga-route" points="${route.map(p => p.join(',')).join(' ')}"/>` : '';
    return `<a class="ga-site" href="#site-${site.id}" data-site="${site.id}" aria-label="${e(site.name)}: ${e(site.kicker)}">${path}${leader}<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="11"/><text class="ga-number" x="${x.toFixed(1)}" y="${(y + 5).toFixed(1)}">${i + 1}</text><text class="ga-label" x="${(x + site.label[0]).toFixed(1)}" y="${(y + site.label[1]).toFixed(1)}" text-anchor="${site.label[2]}">${e(site.short || site.name)}</text></a>`;
  }).join('');
  return `<svg class="ga-map" viewBox="0 0 ${georgia.width} ${georgia.height}" role="img" aria-labelledby="ga-map-title"><title id="ga-map-title">Map of Georgia with the lab’s home in Athens, the GA-72 experiment route, and the Hawkinsville rural route</title><path class="ga-outline" d="${georgia.path}"/><g class="ga-reference" aria-hidden="true"><circle cx="${atlanta[0]}" cy="${atlanta[1]}" r="3.5"/><text x="${(atlanta[0] - 9).toFixed(1)}" y="${(atlanta[1] + 5).toFixed(1)}" text-anchor="end">Atlanta</text></g>${marks}</svg>`;
})();
const fieldCards = fieldSites.map((site, i) => `<article class="field-site" id="site-${site.id}" data-site="${site.id}"><div class="field-site-image"><img ${responsive(site.image, '120px')} alt="${e(site.alt)}" loading="lazy" width="240" height="160"></div><div><p class="eyebrow">0${i + 1} · ${e(site.kicker)}</p><h3>${e(site.name)}</h3><p>${e(site.text)}</p><div class="link-group"><a class="text-link" href="${site.link[0]}">${e(site.link[1])} ${arrow}</a>${site.credit ? `<span class="field-site-credit">${e(site.credit)}</span>` : ''}</div></div></article>`).join('');
